
create schema if not exists private;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, display_name text not null default 'Membre', role text not null default 'pending' check(role in ('pending','admin','member','guest','revoked')));
create function private.my_role() returns text language sql stable security definer set search_path='' as $$ select role from public.profiles where id=auth.uid() $$;
revoke all on function private.my_role() from public; grant usage on schema private to authenticated; grant execute on function private.my_role() to authenticated;
create function private.handle_signup() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,display_name) values(new.id,left(coalesce(new.raw_user_meta_data->>'display_name','Membre'),80)) on conflict do nothing; return new; end $$;
revoke all on function private.handle_signup() from public;
create trigger legends_signup after insert on auth.users for each row execute function private.handle_signup();
create table public.events(id text primary key,title text not null,date date not null,time text not null default '',organizer text not null,place text default '',description text default '',url text default '',visibility text not null default 'group' check(visibility in ('group','couple','personal')),status text not null default 'active' check(status in ('active','discovered','cancelled','proposed')),created_by uuid references auth.users(id) on delete set null,poster_url text default '',attended boolean not null default false);
create function private.can_see_event(e public.events) returns boolean language sql stable security invoker set search_path='' as $$ select private.my_role() in ('admin','member','guest') and (e.visibility='group' or (e.visibility='couple' and private.my_role()='admin') or e.created_by=auth.uid()) $$;
revoke all on function private.can_see_event(public.events) from public; grant execute on function private.can_see_event(public.events) to authenticated;
create table public.votes(id text primary key,event_id text not null references public.events(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,response text not null check(response in ('yes','maybe','no')),unique(event_id,user_id));
create table public.comments(id text primary key,event_id text not null references public.events(id) on delete cascade,author_id uuid not null references auth.users(id) on delete cascade,author_name text not null,body text not null check(length(body)<=1000),created_at timestamptz not null default now());
create table public.tasks(id text primary key,event_id text not null references public.events(id) on delete cascade,label text not null,done boolean not null default false,created_by uuid references auth.users(id) on delete set null);
create table public.expenses(id text primary key,event_id text not null references public.events(id) on delete cascade,label text not null,planned numeric not null default 0 check(planned>=0),actual numeric not null default 0 check(actual>=0),created_by uuid references auth.users(id) on delete set null);
create table public.notifications(id text primary key,user_id uuid not null references auth.users(id) on delete cascade,title text not null,body text default '');
alter table public.profiles enable row level security; revoke all on public.profiles from anon,authenticated; grant select on public.profiles to authenticated;
alter table public.events enable row level security; revoke all on public.events from anon,authenticated; grant select on public.events to authenticated;
alter table public.votes enable row level security; revoke all on public.votes from anon,authenticated; grant select on public.votes to authenticated;
alter table public.comments enable row level security; revoke all on public.comments from anon,authenticated; grant select on public.comments to authenticated;
alter table public.tasks enable row level security; revoke all on public.tasks from anon,authenticated; grant select on public.tasks to authenticated;
alter table public.expenses enable row level security; revoke all on public.expenses from anon,authenticated; grant select on public.expenses to authenticated;
alter table public.notifications enable row level security; revoke all on public.notifications from anon,authenticated; grant select on public.notifications to authenticated;
grant insert,update,delete on public.events,public.votes,public.comments,public.tasks,public.expenses to authenticated;
grant update(role) on public.profiles to authenticated;
create policy profile_read on public.profiles for select to authenticated using(id=auth.uid() or private.my_role()='admin' or (private.my_role() in ('member','guest') and role in ('admin','member','guest')));
create policy profile_approve on public.profiles for update to authenticated using(private.my_role()='admin' and id<>auth.uid()) with check(private.my_role()='admin' and role in ('member','guest','revoked'));
create policy events_read on public.events for select to authenticated using(private.can_see_event(events));
create policy events_insert on public.events for insert to authenticated with check(created_by=auth.uid() and (private.my_role()='admin' or (private.my_role()='member' and status='proposed' and visibility='group')));
create policy events_update on public.events for update to authenticated using(private.my_role()='admin' and private.can_see_event(events)) with check(private.my_role()='admin' and private.can_see_event(events));
create policy events_delete on public.events for delete to authenticated using(private.my_role()='admin' and private.can_see_event(events));
create policy votes_read on public.votes for select to authenticated using(exists(select 1 from public.events e where e.id=event_id));
create policy comments_read on public.comments for select to authenticated using(exists(select 1 from public.events e where e.id=event_id));
create policy tasks_read on public.tasks for select to authenticated using(exists(select 1 from public.events e where e.id=event_id));
create policy expenses_read on public.expenses for select to authenticated using(exists(select 1 from public.events e where e.id=event_id));
create policy votes_insert on public.votes for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.events e where e.id=event_id));
create policy votes_update on public.votes for update to authenticated using(user_id=auth.uid() and exists(select 1 from public.events e where e.id=event_id)) with check(user_id=auth.uid() and exists(select 1 from public.events e where e.id=event_id));
create policy votes_delete on public.votes for delete to authenticated using(user_id=auth.uid() and exists(select 1 from public.events e where e.id=event_id));
create policy comments_insert on public.comments for insert to authenticated with check(author_id=auth.uid() and exists(select 1 from public.events e where e.id=event_id));
create policy comments_delete on public.comments for delete to authenticated using(author_id=auth.uid() and exists(select 1 from public.events e where e.id=event_id));
create policy tasks_insert on public.tasks for insert to authenticated with check(private.my_role() in ('admin','member') and created_by=auth.uid() and exists(select 1 from public.events e where e.id=event_id)); create policy tasks_update on public.tasks for update to authenticated using(private.my_role() in ('admin','member') and exists(select 1 from public.events e where e.id=event_id)) with check(private.my_role() in ('admin','member') and exists(select 1 from public.events e where e.id=event_id)); create policy tasks_delete on public.tasks for delete to authenticated using(private.my_role() in ('admin','member') and exists(select 1 from public.events e where e.id=event_id));
create policy expenses_insert on public.expenses for insert to authenticated with check(private.my_role() in ('admin','member') and created_by=auth.uid() and exists(select 1 from public.events e where e.id=event_id)); create policy expenses_update on public.expenses for update to authenticated using(private.my_role() in ('admin','member') and exists(select 1 from public.events e where e.id=event_id)) with check(private.my_role() in ('admin','member') and exists(select 1 from public.events e where e.id=event_id)); create policy expenses_delete on public.expenses for delete to authenticated using(private.my_role() in ('admin','member') and exists(select 1 from public.events e where e.id=event_id));
create policy notifications_read on public.notifications for select to authenticated using(user_id=auth.uid() and private.my_role() in ('admin','member','guest'));
alter publication supabase_realtime add table public.events,public.votes,public.comments,public.tasks,public.expenses,public.profiles;
